mapper.sql:
oi.is_deleted = false
AND oi.sku_no IN
#{skuNo,jdbcType=VARCHAR}
AND oi.platform_sku IN
#{platformSkuNo,jdbcType=VARCHAR}
AND oi.warehouse_code IN
#{platformWarehouseCode,jdbcType=VARCHAR}
and oi.download_time >= #{params.updateTimeList[0]} and (#{params.updateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > oi.download_time
AND oi.name ILIKE concat('%', #{params.name}::text ,'%')
AND (oi.deliver_onway_qty > 0 OR oi.pending_qty > 0 OR oi.sellable_qty > 0 OR oi.unsellable_qty > 0 OR oi.reserved_qty > 0 OR oi.onway_qty > 0 OR oi.lack_qty > 0 OR oi.frozen_qty > 0 OR oi.shipped_qty > 0)
${params.permissionSql}

mapper.select:
SELECT oi.id, oi.create_time, oi.update_time as updateTime, oi.create_user_name, oi.create_user_id, oi.update_user_name, oi.update_user_id, oi.version, oi.is_deleted, oi.warehouse_code, oi.dict_platform, oi.platform_sku, oi.platform_sku_name, oi.product_name, oi.sku_no, oi.sku_id, oi.deliver_onway_qty as deliverOnwayQty, oi.pending_qty as pendingQty, oi.sellable_qty as sellableQty, oi.unsellable_qty as unsellableQty, oi.reserved_qty as reservedQty, oi.onway_qty as onwayQty, oi.lack_qty as lackQty, oi.frozen_qty as frozenQty, oi.shipped_qty as shippedQty, oi.download_time as downloadTime, opw.warehouse_name as name FROM overseas_inventory as oi LEFT JOIN overseas_provider_warehouse as opw on opw.platform_warehouse_code = oi.warehouse_code
AND oi.id IN
#{id}
